/** Synthetic sessions bundled in public/samples (generated by scripts/generate-samples.mjs). */
export interface SampleSession {
  id: string;
  title: string;
  description: string;
  path: string;
}

export const SAMPLES: SampleSession[] = [
  {
    id: "fix-failing-test",
    title: "Fix a failing test",
    description: "Reproduces the failure, fixes the handler, then runs the suite and tsc.",
    path: "/samples/fix-failing-test.jsonl",
  },
  {
    id: "error-and-retry",
    title: "Error and retry",
    description: "A failed edit, a type error and a broken test, each recovered. Has one truncated line.",
    path: "/samples/error-and-retry.jsonl",
  },
  {
    id: "unverified-success",
    title: "Unverified success",
    description: "Reports that all tests pass without running them, and deletes the lockfile.",
    path: "/samples/unverified-success.jsonl",
  },
];

export function findSample(id: string | null): SampleSession | undefined {
  return SAMPLES.find((sample) => sample.id === id);
}
